// @ts-check
// Shared helpers for the site's JavaScript pages (plain ES modules, no build
// step; see docs/js-conversion-plan.md). Paths are resolved from this file,
// so pages at any depth can import it.

/** URL of a file under site/vendor/ (see vendor/vendor.yml). */
export const vendor = (p) => new URL(`../vendor/${p}`, import.meta.url).href;

/** URL of a file under site/data/ (generated by summarize_catalog.py). */
export const dataUrl = (p) => new URL(`../data/${p}`, import.meta.url).href;

/**
 * Fetch JSON from site/data/. With `fallback`, a missing or bad file gives
 * the fallback instead of an error (optional files such as variables.json).
 * @param {string} p
 * @param {any} [fallback]
 */
export async function loadJson(p, fallback) {
  try {
    const r = await fetch(dataUrl(p));
    if (!r.ok) throw new Error(`${p}: HTTP ${r.status}`);
    return await r.json();
  } catch (err) {
    if (fallback !== undefined) return fallback;
    throw err;
  }
}

/** Add a stylesheet from vendor/ once. */
export function vendorCss(p) {
  const href = vendor(p);
  if (!document.querySelector(`link[href="${href}"]`)) {
    document.head.append(Object.assign(document.createElement("link"), {rel: "stylesheet", href}));
  }
}

/** Values in _variables.yml ending in _TBD are placeholders. */
export const isPlaceholder = (v) => !v || /_TBD$/.test(v);

/** 1234567 -> "1,234,567"; digits = max fraction digits. */
export const fmt = (x, digits = 0) =>
  (x ?? 0).toLocaleString(undefined, {maximumFractionDigits: digits});

/** Size in GB as "84.6 GB" or, from 1000 GB, "1.23 TB". */
export const size = (gb) => (gb >= 1000 ? `${fmt(gb / 1000, 2)} TB` : `${fmt(gb, 1)} GB`);

/** "1 file" / "3 files". */
export const plural = (n, one, many = `${one}s`) => `${fmt(n)} ${n === 1 ? one : many}`;

/**
 * Create an element: el("a", {href: "x", class: "y"}, "text", child, ...).
 * Attributes starting with "on" are event listeners; null/false are skipped.
 * @param {string} tag
 * @param {Record<string, any>} [attrs]
 * @param {...any} children
 * @returns {HTMLElement}
 */
export function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v == null || v === false) continue;
    if (k.startsWith("on")) node.addEventListener(k.slice(2), v);
    else if (k === "class") node.className = v;
    else if (k in node && typeof v !== "string") node[k] = v;
    else node.setAttribute(k, v === true ? "" : String(v));
  }
  for (const c of children.flat(Infinity)) {
    if (c == null || c === false) continue;
    node.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return node;
}

/** Replace an element's children; null/false/"" are skipped, arrays flattened. */
export function put(node, ...children) {
  node.replaceChildren(...children.flat(Infinity).filter((c) => c != null && c !== false && c !== "")
    .map((c) => (c instanceof Node ? c : document.createTextNode(String(c)))));
}

/** A code block with a Copy button (same markup as the OJS pages). */
export function copyBlock(text, lang = "") {
  const btn = el("button", {type: "button", class: "btn btn-sm btn-outline-secondary mb-2"}, "Copy");
  btn.addEventListener("click", () =>
    navigator.clipboard.writeText(text).then(() => {
      btn.textContent = "Copied";
      setTimeout(() => (btn.textContent = "Copy"), 1500);
    })
  );
  return el("div", {class: "get-data-block"}, btn,
    el("pre", {class: `sourceCode ${lang}`}, el("code", {}, text)));
}

/** GitHub issue form for a problem with one dataset. */
export function reportUrl(config, d) {
  const u = new URL(`https://github.com/${config.github_repo}/issues/new`);
  u.searchParams.set("template", "report-problem.yml");
  u.searchParams.set("title", `[Problem]: ${d.dataset_id}`);
  u.searchParams.set("dataset_id", d.dataset_id);
  u.searchParams.set("path", d.relative_path);
  return u.href;
}

// Vocabulary key shared with summarize_catalog.VOCAB_JOIN_KEYS.
const VOCAB_JOIN_KEYS = ["collection", "product", "table_id", "level", "variable_id"];
const vocabKey = (d) => VOCAB_JOIN_KEYS.map((k) => d[k] ?? "").join("|");

/**
 * Join the store vocabulary (variables.json, one row per NetCDF variable) to
 * the dataset summary. Adds to each dataset:
 *   variables: its variable names (variable_id split on ","; datasets of the
 *     generic products hold several variables per file),
 *   standard_names, long_name (joined), var_tip (tooltip text),
 *   search_text (lower case: id, facets, long and standard names, with "-"
 *     and "_" as spaces so "surface" finds "Near-Surface").
 * Returns {rows, varInfo}: varInfo maps a variable name to {long_name, units,
 * standard_name} for facet labels (first definition seen).
 */
export function joinVocabulary(summary, vocab) {
  const byKey = new Map();
  for (const v of vocab) {
    const k = vocabKey(v);
    if (!byKey.has(k)) byKey.set(k, []);
    byKey.get(k).push(v);
  }
  const varInfo = new Map();
  const rows = summary.map((d) => {
    const vs = byKey.get(vocabKey(d)) ?? [];
    const variables = d.variable_id ? d.variable_id.split(",") : [];
    // vocabulary row for one variable name: by NetCDF name, or the single
    // row of a one-variable dataset (ERA5: variable_id 2m_temperature, nc t2m)
    const rowFor = (name) => vs.find((v) => v.nc_name === name) ?? (variables.length === 1 ? vs[0] : undefined);
    for (const name of variables) {
      const v = rowFor(name);
      if (v && !varInfo.has(name)) {
        varInfo.set(name, {long_name: v.long_name, units: v.units, standard_name: v.standard_name});
      }
    }
    const standard_names = [...new Set(vs.map((v) => v.standard_name).filter(Boolean))];
    const long_name = vs.map((v) => v.long_name).filter(Boolean).join("; ") || null;
    const var_tip = vs.map((v) => [
      `${v.nc_name}: ${v.long_name ?? "(no long name)"}${v.units ? ` [${v.units}]` : ""}`,
      v.standard_name ? `standard name: ${v.standard_name}` : null
    ].filter(Boolean).join("\n")).join("\n\n") || null;
    const search_text = [
      d.dataset_id, d.source_id, d.product, d.experiment_id, d.variable_id,
      ...vs.flatMap((v) => [v.nc_name, v.long_name, v.standard_name])
    ].filter(Boolean).join(" ").replace(/[-_.,]/g, " ").toLowerCase();
    return {...d, variables, standard_names, long_name, var_tip, search_text};
  });
  return {rows, varInfo};
}

/** Search words (lower case); a row matches when it contains every word. */
export const searchWords = (q) =>
  q.toLowerCase().replace(/[-_.,]/g, " ").split(/\s+/).filter(Boolean);
